scss.scss_field:
.custom-text{
  letter-spacing: 4px;
}
.custom-text-1{
  letter-spacing: 7px;
}
.custom-img{
  margin-left: 2px;
  margin-right: 2px;
img{
  transform-origin: center;
transition: scale 8s cubic-bezier(.25,.46,.45,.94);
}
&:hover{
  img{
    scale: 1.2;
  }
}
